/// `syntax/highlight_snippet`: stateless tree-sitter over a snippet — real captures for a known
/// language, the fence alias table resolving short names, and an empty (not error) result for an
/// unknown language.
#[tokio::test]
async fn highlight_snippet_uses_registry_and_aliases() {
    use aether_protocol::syntax::{SyntaxHighlightSnippet, SyntaxHighlightSnippetParams};
    let (_server, mut ws, _buffer_id) = setup_with_buffer("x\n").await;

    let r = send_request::<SyntaxHighlightSnippet>(
        &mut ws,
        &SyntaxHighlightSnippetParams {
            language: "rust".into(),
            text: "fn main() { let s = \"hi\"; }".into(),
        },
    )
    .await;
    assert!(
        r.highlights.iter().any(|h| h.kind == "keyword"),
        "rust snippet yields keyword captures, got {:?}",
        r.highlights
    );
    assert!(
        r.highlights.iter().any(|h| h.kind.starts_with("string")),
        "rust snippet yields string captures"
    );

    // Fence short names resolve through the same alias table (`rs` → rust).
    let r = send_request::<SyntaxHighlightSnippet>(
        &mut ws,
        &SyntaxHighlightSnippetParams {
            language: "rs".into(),
            text: "fn x() {}".into(),
        },
    )
    .await;
    assert!(!r.highlights.is_empty(), "alias resolves");

    // Unknown language: empty, not an error — callers fire-and-adopt.
    let r = send_request::<SyntaxHighlightSnippet>(
        &mut ws,
        &SyntaxHighlightSnippetParams {
            language: "no-such-lang".into(),
            text: "whatever".into(),
        },
    )
    .await;
    assert!(r.highlights.is_empty());

    // The client sends the fence's full info string; metadata after the language — space- or
    // comma-separated (```rust ignore / ```rust,no_run) — doesn't defeat resolution.
    for (_, info) in [(13, "rust ignore"), (14, "rust,no_run")] {
        let r = send_request::<SyntaxHighlightSnippet>(
            &mut ws,
            &SyntaxHighlightSnippetParams {
                language: info.into(),
                text: "fn x() {}".into(),
            },
        )
        .await;
        assert!(
            r.highlights.iter().any(|h| h.kind == "keyword"),
            "info string {info:?} should still resolve to rust, got {:?}",
            r.highlights
        );
    }
}

/// Read frames until a change signal (`buffer/changed` or `viewport/lines_changed`) arrives;
/// returns which one, plus its params. Used to pin *which* branch of the edit-push range gate
/// fired, which `expect_notification`'s skip-unrelated behaviour can't distinguish.
async fn next_change_signal(ws: &mut Ws) -> (String, serde_json::Value) {
    loop {
        let text = next_text(ws).await;
        let inbound: ClientInbound = serde_json::from_str(&text).expect("parseable");
        if let ClientInbound::Notification(n) = inbound {
            if n.method == BufferChanged::NAME
                || n.method == aether_protocol::viewport::ViewportLinesChanged::NAME
            {
                return (n.method, n.params);
            }
        }
    }
}

/// A typed edit outside another client's pushed window sends that client the revision-only
/// `buffer/changed` — the `viewport/lines_changed` range gate would otherwise leave a
/// whole-document consumer (the markdown reading view) unaware of the mutation. An edit inside
/// the window still sends the full `viewport/lines_changed`.
#[tokio::test]
async fn out_of_window_edit_pushes_buffer_changed() {
    // 40 lines, so a 10-row viewport at the top leaves plenty of buffer outside its range.
    let content: String = (0..40).map(|i| format!("line {i}\n")).collect();
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("doc.md"), &content).unwrap();
    let dir_path = dir.path().to_path_buf();
    let server = spawn_for_test("test-proj", vec![dir_path]).await.unwrap();

    // Client 1: the editor (no viewport — edits don't need one).
    let mut ws = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: false,
        },
    )
    .await;
    let open: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("doc.md", None)).await;
    let buffer_id = open.buffer_id;

    // Client 2: the reader, viewport pinned to the top 10 rows.
    let mut ws2 = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws2,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: false,
        },
    )
    .await;
    // As the *editor*: presented as the reader the document is loaded whole and nothing is ever
    // outside the window — see `a_markdown_file_is_presented_as_the_reader_by_default`.
    let editor: ViewOpenResult = send_request::<ViewOpen>(
        &mut ws2,
        &ViewOpenParams {
            kind: Some(aether_protocol::ui::ViewKind::Editor),
            ..attach_open_params(buffer_id, None)
        },
    )
    .await;
    let _: ViewportSubscribeResult =
        send_request::<ViewportSubscribe>(&mut ws2, &transient_sub_params(editor.buffer_id)).await;

    // Client 1 edits far below client 2's window → client 2 gets the revision-only signal.
    let _: CursorState = send_request::<CursorMove>(
        &mut ws,
        &CursorMoveParams {
            buffer_id,
            motion: Motion::Goto {
                position: LogicalPosition { line: 35, col: 0 },
            },
            extend_selection: false,
        },
    )
    .await;
    let r: EditResult = send_request::<InputText>(
        &mut ws,
        &InputTextParams {
            buffer_id,
            text: "!".into(),
            select_pasted: false,
            replace_selection: false,
            at: Some(SelectionEdge::Start),
        },
    )
    .await;
    let (method, params) = next_change_signal(&mut ws2).await;
    assert_eq!(
        method,
        BufferChanged::NAME,
        "out-of-window edit → buffer/changed"
    );
    let changed: BufferChangedParams = serde_json::from_value(params).unwrap();
    assert_eq!(changed.buffer_id, buffer_id);
    assert_eq!(changed.revision, r.revision);

    // Client 1 edits inside client 2's window → the full window render as before.
    let _: CursorState = send_request::<CursorMove>(
        &mut ws,
        &CursorMoveParams {
            buffer_id,
            motion: Motion::Goto {
                position: LogicalPosition { line: 0, col: 0 },
            },
            extend_selection: false,
        },
    )
    .await;
    let r2: EditResult = send_request::<InputText>(
        &mut ws,
        &InputTextParams {
            buffer_id,
            text: "!".into(),
            select_pasted: false,
            replace_selection: false,
            at: Some(SelectionEdge::Start),
        },
    )
    .await;
    let (method, params) = next_change_signal(&mut ws2).await;
    assert_eq!(
        method,
        aether_protocol::viewport::ViewportLinesChanged::NAME,
        "in-window edit → viewport/lines_changed"
    );
    let lc: aether_protocol::viewport::ViewportLinesChangedParams =
        serde_json::from_value(params).unwrap();
    assert_eq!(lc.revision, r2.revision);

    drop(server);
}

/// Plain HTTP GET against the test server (the ws port doubles as the HTTP port), returning
/// `(status_line, headers, body)`. Carries a loopback `Host` header — the server's rebinding
/// defense rejects requests without one.
async fn http_get(ws_url: &str, path: &str) -> (String, String, Vec<u8>) {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    let authority = ws_url
        .trim_start_matches("ws://")
        .split('/')
        .next()
        .expect("authority");
    let mut stream = tokio::net::TcpStream::connect(authority)
        .await
        .expect("connect");
    let req = format!("GET {path} HTTP/1.1\r\nHost: {authority}\r\nConnection: close\r\n\r\n");
    stream.write_all(req.as_bytes()).await.unwrap();
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf).await.unwrap();
    let header_end = buf
        .windows(4)
        .position(|w| w == b"\r\n\r\n")
        .map(|p| p + 4)
        .unwrap_or(buf.len());
    let head = String::from_utf8_lossy(&buf[..buf.len().min(header_end)]).to_string();
    let status = head.lines().next().unwrap_or_default().to_string();
    (status, head, buf[header_end..].to_vec())
}

/// The web reading view's image route: serves files relative to a buffer's directory, confined to
/// the buffer's workspace root after canonicalization — `.` and symlink escapes 404, as do unknown
/// buffers and non-image extensions.
#[tokio::test]
async fn buffer_asset_route_serves_and_confines() {
    let dir = tempfile::tempdir().unwrap();
    let outside = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("doc.md"), "![d](img.png)\n").unwrap();
    std::fs::write(dir.path().join("img.png"), b"PNGDATA").unwrap();
    std::fs::write(outside.path().join("secret.png"), b"SECRET").unwrap();
    #[cfg(unix)]
    std::os::unix::fs::symlink(
        outside.path().join("secret.png"),
        dir.path().join("leak.png"),
    )
    .unwrap();
    let dir_path = dir.path().to_path_buf();
    let outside_path = outside.path().to_path_buf();

    let server = spawn_for_test("test-proj", vec![dir_path.clone()])
        .await
        .unwrap();
    let mut ws = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: false,
        },
    )
    .await;
    let open: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("doc.md", None)).await;
    let id = open.buffer_id;
    let url = server.ws_url();

    // The happy path: an image beside the document — with the hardening headers (nosniff pins
    // the type; `sandbox` neuters scripts when an SVG asset is opened as a page, which would
    // otherwise execute same-origin with the editor client).
    let (status, head, body) = http_get(&url, &format!("/asset/{id}/img.png")).await;
    assert!(status.contains("200"), "got {status}");
    assert_eq!(body, b"PNGDATA");
    assert!(
        head.contains("X-Content-Type-Options: nosniff"),
        "asset responses carry nosniff, got:\n{head}"
    );
    assert!(
        head.contains("Content-Security-Policy: sandbox"),
        "asset responses carry CSP sandbox, got:\n{head}"
    );

    // A parent-relative path that stays inside the root is legitimate (the web shell encodes
    // the whole relative path as one segment, so the `..` reaches the server un-collapsed).
    std::fs::create_dir_all(dir_path.join("docs")).unwrap();
    std::fs::write(dir_path.join("docs/nested.md"), "![up](../img.png)\n").unwrap();
    let nested: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("docs/nested.md", None)).await;
    let (status, _, body) =
        http_get(&url, &format!("/asset/{}/..%2Fimg.png", nested.buffer_id)).await;
    assert!(
        status.contains("200"),
        "in-root ..%2F must serve, got {status}"
    );
    assert_eq!(body, b"PNGDATA");

    // A root-relative source (leading `/`, GitHub semantics) resolves against the buffer's
    // containing root, not the filesystem.
    let (status, _, body) =
        http_get(&url, &format!("/asset/{}/%2Fimg.png", nested.buffer_id)).await;
    assert!(
        status.contains("200"),
        "root-relative %2F must serve, got {status}"
    );
    assert_eq!(body, b"PNGDATA");

    // …and it is confined exactly like a relative path.
    let root_escape = format!(
        "/asset/{id}/%2F..%2F{}%2Fsecret.png",
        outside_path.file_name().unwrap().to_string_lossy()
    );
    let (status, _, _) = http_get(&url, &root_escape).await;
    assert!(
        status.contains("404"),
        "root-relative traversal must 404, got {status}"
    );

    // `..` traversal out of the root → 404 (canonical-prefix check).
    let rel_escape = format!(
        "/asset/{id}/..%2F{}%2Fsecret.png",
        outside_path.file_name().unwrap().to_string_lossy()
    );
    let (status, _, _) = http_get(&url, &rel_escape).await;
    assert!(status.contains("404"), "traversal must 404, got {status}");

    // A symlink pointing outside the root → 404 after canonicalization.
    #[cfg(unix)]
    {
        let (status, _, body) = http_get(&url, &format!("/asset/{id}/leak.png")).await;
        assert!(
            status.contains("404"),
            "symlink escape must 404, got {status} ({:?})",
            String::from_utf8_lossy(&body)
        );
    }

    // Unknown buffer and non-image extensions → 404.
    let (status, _, _) = http_get(&url, "/asset/9999/img.png").await;
    assert!(
        status.contains("404"),
        "unknown buffer must 404, got {status}"
    );
    let (status, _, _) = http_get(&url, &format!("/asset/{id}/doc.md")).await;
    assert!(status.contains("404"), "non-image must 404, got {status}");

    drop(server);
}

/// `view/open` params attaching to an existing buffer by id.
fn attach_open_params(buffer_id: u64, transient: Option<bool>) -> ViewOpenParams {
    ViewOpenParams {
        view_id: Some(view_of(buffer_id)),
        path_index: None,
        relative_path: None,
        language: None,
        create_if_missing: false,
        jump_to: None,
        transient,
        ..Default::default()
    }
}

/// A dropped connection — a closed native-client tab, a closed browser tab — hides everything
/// that client was showing: its viewed transients orphan-close on disconnect like any other
/// hide, so Ctrl-t/Ctrl-w tab churn doesn't leave scratch buffers behind.
#[tokio::test]
async fn transient_buffer_closes_on_disconnect() {
    let (server, mut ws) = setup_transient_workspace().await;
    let scratch: ViewOpenResult = send_request::<ViewOpen>(
        &mut ws,
        &ViewOpenParams {
            path_index: None,
            relative_path: None,
            language: None,
            create_if_missing: false,
            jump_to: None,
            transient: Some(true),
            ..Default::default()
        },
    )
    .await;
    assert!(scratch.transient, "fresh scratch opened transient");
    let _: ViewportSubscribeResult =
        send_request::<ViewportSubscribe>(&mut ws, &transient_sub_params(scratch.buffer_id)).await;
    drop(ws); // the tab closes its connection

    // The server processes the close on its own task, so wait for it to land rather than guessing
    // at how long it takes.
    wait_for_client_count(&server, 0).await;

    let mut ws2 = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws2,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: false,
        },
    )
    .await;
    let err =
        send_request_expect_err::<ViewOpen>(&mut ws2, &attach_open_params(scratch.buffer_id, None))
            .await;
    assert!(
        err.contains("unknown view_id"),
        "presenting the orphaned transient should fail (got: {err})"
    );
}

/// The core lifecycle: a transient buffer dies when the client's viewport moves elsewhere.
#[tokio::test]
async fn transient_buffer_closes_when_hidden() {
    let (server, mut ws) = setup_transient_workspace().await;
    let a: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("a.txt", Some(true))).await;
    assert!(a.transient, "open with transient:true reports the flag");
    let _: ViewportSubscribeResult =
        send_request::<ViewportSubscribe>(&mut ws, &transient_sub_params(a.buffer_id)).await;

    // Switch to b: open + subscribe. The subscribe supersedes a's viewport, hiding a → closed.
    let b: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("b.txt", None)).await;
    assert!(!b.transient, "open without the flag is permanent");
    let _: ViewportSubscribeResult =
        send_request::<ViewportSubscribe>(&mut ws, &transient_sub_params(b.buffer_id)).await;

    let err =
        send_request_expect_err::<ViewOpen>(&mut ws, &attach_open_params(a.buffer_id, None)).await;
    assert!(
        err.contains("unknown view_id"),
        "hidden transient buffer should be closed, got: {err}"
    );
    drop(server);
}

/// A buffer opened without the flag survives being hidden — the pre-transient behavior.
#[tokio::test]
async fn permanent_buffer_survives_hiding() {
    let (server, mut ws) = setup_transient_workspace().await;
    let a: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("a.txt", None)).await;
    let _: ViewportSubscribeResult =
        send_request::<ViewportSubscribe>(&mut ws, &transient_sub_params(a.buffer_id)).await;
    let b: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("b.txt", None)).await;
    let _: ViewportSubscribeResult =
        send_request::<ViewportSubscribe>(&mut ws, &transient_sub_params(b.buffer_id)).await;
    let again: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &attach_open_params(a.buffer_id, None)).await;
    assert_eq!(again.buffer_id, a.buffer_id);
    drop(server);
}

/// The first edit promotes: an edited transient buffer survives being hidden.
#[tokio::test]
async fn edit_promotes_transient_buffer() {
    let (server, mut ws) = setup_transient_workspace().await;
    let a: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("a.txt", Some(true))).await;
    let _: ViewportSubscribeResult =
        send_request::<ViewportSubscribe>(&mut ws, &transient_sub_params(a.buffer_id)).await;
    let _: EditResult = send_request::<InputText>(
        &mut ws,
        &InputTextParams {
            buffer_id: a.buffer_id,
            text: "x".into(),
            select_pasted: false,
            replace_selection: false,
            at: None,
        },
    )
    .await;

    let b: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("b.txt", None)).await;
    let _: ViewportSubscribeResult =
        send_request::<ViewportSubscribe>(&mut ws, &transient_sub_params(b.buffer_id)).await;

    let again: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &attach_open_params(a.buffer_id, None)).await;
    assert!(!again.transient, "the edit promoted the buffer");
    drop(server);
}

/// Explicit pin (`view/open { transient: false }`) promotes without an edit.
#[tokio::test]
async fn pin_promotes_transient_buffer() {
    let (server, mut ws) = setup_transient_workspace().await;
    let a: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("a.txt", Some(true))).await;
    let _: ViewportSubscribeResult =
        send_request::<ViewportSubscribe>(&mut ws, &transient_sub_params(a.buffer_id)).await;

    let pinned: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &attach_open_params(a.buffer_id, Some(false))).await;
    assert!(!pinned.transient, "pin reports the flag cleared");

    let b: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &file_open_params("b.txt", None)).await;
    let _: ViewportSubscribeResult =
        send_request::<ViewportSubscribe>(&mut ws, &transient_sub_params(b.buffer_id)).await;
    let again: ViewOpenResult =
        send_request::<ViewOpen>(&mut ws, &attach_open_params(a.buffer_id, None)).await;
    assert_eq!(again.buffer_id, a.buffer_id);
    drop(server);
}

